@startuml

class EBike {
  + frame : Frame
  + wheels : Wheel[]
  + driveSystem : DriveSystem
  + battery : Battery?
  + controller : Controller
}

class Frame {
  - material : string
}

class Wheel {
  - diameter : float
}

class DriveSystem {
  - motor : Motor
}

class Battery {
  - energy : double
  - unit : string
}

abstract class Controller {
  + state : string
  + controlBattery(battery : Battery) : void
  + commandDriveSystem(driveSystem : DriveSystem) : void
}

class BasicController extends Controller {}

class AdvancedController extends Controller {
  + estimateMaintenanceDate() : Date
}

@enduml

